// ListPendingJobs returns the jobs of the type @job_type (every type when empty) in the state
// @state at @now (every state when empty; the states of ADR-0064 section 3: running while the
// lease holds, otherwise queued before the first run and retrying after it), the earliest run_at
// first, after the position (@after_run_at, @after_id); an empty @after_id starts at the first.
func (q *Queries) ListPendingJobs(ctx context.Context, arg ListPendingJobsParams) ([]ListPendingJobsRow, error) {
	rows, err := q.db.QueryContext(ctx, listPendingJobs,
		arg.JobType,
		arg.State,
		arg.Now,
		arg.AfterID,
		arg.AfterRunAt,
		arg.BatchLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListPendingJobsRow{}
	for rows.Next() {
		var i ListPendingJobsRow
		if err := rows.Scan(
			&i.ID,
			&i.Type,
			&i.Payload,
			&i.IdempotencyKey,
			&i.OrderingKey,
			&i.Attempt,
			&i.RunAt,
			&i.LockedBy,
			&i.LockedUntil,
			&i.LastError,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const nextJobOfKey = `-- name: NextJobOfKey :one
SELECT id, run_at FROM jobs WHERE ordering_key = ? ORDER BY created_at, id LIMIT 1
`

type NextJobOfKeyRow struct {
	ID    string
	RunAt int64
}

func (q *Queries) NextJobOfKey(ctx context.Context, orderingKey sql.NullString) (NextJobOfKeyRow, error) {
	row := q.db.QueryRowContext(ctx, nextJobOfKey, orderingKey)
	var i NextJobOfKeyRow
	err := row.Scan(&i.ID, &i.RunAt)
	return i, err
}

const releaseJob = `-- name: ReleaseJob :execrows
UPDATE jobs
SET locked_by = NULL, locked_until = NULL,
  attempt = ?1, run_at = ?2, last_error = ?3
WHERE id = ?4 AND locked_by = ?5 AND attempt = ?6
`

type ReleaseJobParams struct {
	NewAttempt int64
	RunAt      int64
	LastError  sql.NullString
	ID         string
	Worker     sql.NullString
	Attempt    int64
}

func (q *Queries) ReleaseJob(ctx context.Context, arg ReleaseJobParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, releaseJob,
		arg.NewAttempt,
		arg.RunAt,
		arg.LastError,
		arg.ID,
		arg.Worker,
		arg.Attempt,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const requeueDeadJob = `-- name: RequeueDeadJob :execrows
INSERT INTO jobs (id, type, payload, idempotency_key, ordering_key, trace_parent, attempt, run_at, created_at)
SELECT d.id, d.type, d.payload, d.idempotency_key, d.ordering_key, d.trace_parent, 0, ?1, d.created_at
FROM dead_jobs AS d
WHERE d.id = ?2
ON CONFLICT (idempotency_key) DO NOTHING
`

type RequeueDeadJobParams struct {
	RunAt int64
	ID    string
}

func (q *Queries) RequeueDeadJob(ctx context.Context, arg RequeueDeadJobParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, requeueDeadJob, arg.RunAt, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}
